#!/usr/bin/env node
// Tree-sitter grammar integrity gate (security report Phase 4, item 20 /
// VF-30). The vendored grammar set under
// `packages/tools/src/codebase-index/wasm/` (13 grammars + the
// tree-sitter-runtime.wasm engine) is executed as native-adjacent code by
// every indexed parse. Nothing previously verified that the committed bytes
// are the bytes that were reviewed when the set was vendored — a tampered or
// accidentally-replaced .wasm would load silently.
//
// This script pins the set with a committed sha256 manifest
// (`wasm/checksums.json`, generated by --write) and verifies it:
//   - CI (build job in ci.yml): `node scripts/check-tree-sitter-wasm.mjs`
//     fails the build on any mismatch, missing grammar, or unexpected file.
//   - Local regeneration after an INTENTIONAL grammar bump:
//     `node scripts/check-tree-sitter-wasm.mjs --write` — then review the
//     manifest diff like any other dependency change.
//
// The runtime (`tree-sitter-parser.ts`) performs the same check lazily at
// first load of each grammar, falling back to the regex parser on mismatch.
//
// Exit codes: 0 verified; 1 verification failure (tamper/drift);
// 2 setup error (no manifest yet).
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const WASM_DIR = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../packages/tools/src/codebase-index/wasm',
);
const MANIFEST = path.join(WASM_DIR, 'checksums.json');

/** Recursively collect .wasm files relative to WASM_DIR, forward slashes. */
function collectWasmFiles(dir, base = dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...collectWasmFiles(full, base));
    else if (entry.name.endsWith('.wasm')) {
      out.push(path.relative(base, full).split(path.sep).join('/'));
    }
  }
  return out.sort();
}

function sha256(file) {
  return createHash('sha256').update(readFileSync(file)).digest('hex');
}

function buildManifest() {
  const files = collectWasmFiles(WASM_DIR);
  if (files.length === 0) {
    console.error(`No .wasm files found under ${WASM_DIR} — wrong CWD or moved directory?`);
    process.exit(2);
  }
  const manifest = {};
  for (const rel of files) manifest[rel] = sha256(path.join(WASM_DIR, rel));
  return manifest;
}

if (process.argv.includes('--write')) {
  const manifest = buildManifest();
  writeFileSync(MANIFEST, `${JSON.stringify(manifest, null, 2)}\n`);
  console.log(`Wrote ${Object.keys(manifest).length} checksums to ${path.relative(process.cwd(), MANIFEST)}`);
  process.exit(0);
}

let manifest;
try {
  manifest = JSON.parse(readFileSync(MANIFEST, 'utf8'));
} catch {
  console.error(
    `Manifest missing or unreadable: ${MANIFEST}\nRun \`node scripts/check-tree-sitter-wasm.mjs --write\` once, then review the committed diff.`,
  );
  process.exit(2);
}

const onDisk = buildManifest();
const problems = [];
for (const rel of Object.keys(manifest)) {
  if (!(rel in onDisk)) problems.push(`missing: ${rel}`);
  else if (onDisk[rel] !== manifest[rel]) problems.push(`checksum mismatch: ${rel}`);
}
for (const rel of Object.keys(onDisk)) {
  if (!(rel in manifest)) problems.push(`unexpected file (not in manifest): ${rel}`);
}

if (problems.length > 0) {
  console.error(`tree-sitter wasm integrity FAILED (${problems.length}):`);
  for (const p of problems) console.error(`  - ${p}`);
  console.error(
    '\nIf this change is intentional, regenerate with --write and review the manifest diff as a dependency change.',
  );
  process.exit(1);
}
console.log(`tree-sitter wasm integrity OK — ${Object.keys(onDisk).length} files match checksums.json`);
